const compareCmd = `python3 -B -c 'from pathlib import Path; import subprocess,sys,tempfile; sys.path.insert(0,"tools"); from i18nlib.config import load_manifest; from i18nlib.locale_model import LocaleLoader; from i18nlib.runtime import LuaRuntime; source="#LIGHT_RED##Target# is out of sight of its master; direct control will break!"; old="#LIGHT_RED##Target#在主人视野外；直接控制中断了！"; new="#LIGHT_RED##Target#在主人视野外；直接控制即将中断！"; loader=LocaleLoader(LuaRuntime(load_manifest())); results=[]\nfor name in ("mod-tome.lua","tome-orcs.lua"):\n data=subprocess.check_output(["git","show","HEAD:"+name]); f=tempfile.NamedTemporaryFile(suffix=".lua"); f.write(data); f.flush(); before=loader.load_path(Path(f.name),logical_path=name).records; after=loader.load_path(Path(name),logical_path=name).records; assert len(before)==len(after); diffs=[]\n for a,b in zip(before,after):\n  aa={k:v for k,v in a.items() if k!="line"}; bb={k:v for k,v in b.items() if k!="line"}\n  if aa!=bb: diffs.append((a,b)); assert {k:v for k,v in aa.items() if k!="target"}=={k:v for k,v in bb.items() if k!="target"}\n assert len(diffs)==1; a,b=diffs[0]; assert a.get("source")==source and a.get("source_tag")=="_t" and a.get("target")==old and b.get("target")==new; results.append((name,len(after),len(diffs)))\ncults=loader.load_path(Path("tome-cults.lua"),logical_path="tome-cults.lua").records; matches=[r for r in cults if r.get("source")==source and r.get("source_tag")=="_t"]; assert len(matches)==1 and matches[0].get("target")==new; print("verified=true runtime=manifest-compatible-LuaJIT results="+repr(results)+" cults_target_byte_identical=true")'`;
const calls = [
  tools.exec_command({cmd:compareCmd,workdir:"/workspace/tome4-chinese-translation",yield_time_ms:30000,max_output_tokens:6000,sandbox_permissions:"require_escalated",justification:"允许我运行 manifest-compatible LuaJIT 有界加载比较，确认两文件相对 HEAD 各恰一条 target 改动且与 Cults 字节一致吗？"}),
  tools.exec_command({cmd:"python3 -B tools/scan_runtime_collisions.py",workdir:"/workspace/tome4-chinese-translation",yield_time_ms:30000,max_output_tokens:12000,sandbox_permissions:"require_escalated",justification:"允许我运行跨组件运行时键冲突扫描；它会更新已忽略的可重生成报告吗？",prefix_rule:["python3","-B","tools/scan_runtime_collisions.py"]}),
  tools.exec_command({cmd:"python3 -B tools/i18n lint --strict",workdir:"/workspace/tome4-chinese-translation",yield_time_ms:30000,max_output_tokens:16000,sandbox_permissions:"require_escalated",justification:"允许我运行 strict i18n lint；它会在已忽略的 `.artifacts/i18n/` 中写入可重生成报告吗？",prefix_rule:["python3","-B","tools/i18n","lint"]}),
  tools.exec_command({cmd:"git diff --check",workdir:"/workspace/tome4-chinese-translation",yield_time_ms:30000,max_output_tokens:4000,sandbox_permissions:"require_escalated",justification:"允许我运行 `git diff --check` 检查当前未提交差异的空白错误吗？",prefix_rule:["git","diff","--check"]})
];
const results = await Promise.all(calls);
results.forEach((r,i)=>{ text(`--- check ${i+1} exit=${r.exit_code} ---\n${r.output}`); });
